INSERT INTO `p3_pair_summary` VALUES ('development',1,'BRCA1',672,'BRCA1',12189,'Brca1','resolved','ortholog_found','reviewed_found','P38398','Breast cancer type 1 susceptibility protein','GO:0000151 ubiquitin ligase complex; GO:0000152 nuclear ubiquitin ligase complex; GO:0000724 double-strand break repair via homologous recombination; GO:0000794 condensed nuclear chromosome; GO:0000800 lateral element; GO:0000931 gamma-tubulin ring complex; GO:0000976 transcription cis-regulatory region binding; GO:0002039 p53 binding; GO:0003677 DNA binding; GO:0003684 damaged DNA binding; GO:0003713 transcription coactivator activity; GO:0003723 RNA binding; GO:0004842 ubiquitin-protein transferase activity; GO:0005634 nucleus; GO:0005654 nucleoplasm; GO:0005694 chromosome; GO:0005737 cytoplasm; GO:0005886 plasma membrane; GO:0006281 DNA repair; GO:0006282 regulation of DNA repair; GO:0006301 DNA damage tolerance; GO:0006302 double-strand break repair; GO:0006338 chromatin remodeling; GO:0006357 regulation of transcription by RNA polymerase II; GO:0006974 DNA damage response; GO:0007059 chromosome segregation; GO:0007095 mitotic G2 DNA damage checkpoint signaling; GO:0008270 zinc ion binding; GO:0008630 intrinsic apoptotic signaling pathway in response to DNA damage; GO:0010212 response to ionizing radiation; GO:0010575 positive regulation of vascular endothelial growth factor production; GO:0010628 positive regulation of gene expression; GO:0015631 tubulin binding; GO:0016567 protein ubiquitination; GO:0016604 nuclear body; GO:0019899 enzyme binding; GO:0030308 negative regulation of cell growth; GO:0031436 BRCA1-BARD1 complex; GO:0031625 ubiquitin protein ligase binding; GO:0032991 protein-containing complex; GO:0033147 negative regulation of intracellular estrogen receptor signaling pathway; GO:0035825 homologous recombination; GO:0042802 identical protein binding; GO:0044027 negative regulation of gene expression via chromosomal CpG island methylation; GO:0044818 mitotic G2/M transition checkpoint; GO:0045717 negative regulation of fatty acid biosynthetic process; GO:0045739 positive regulation of DNA repair; GO:0045766 positive regulation of angiogenesis; GO:0045786 negative regulation of cell cycle; GO:0045892 negative regulation of DNA-templated transcription; GO:0045893 positive regulation of DNA-templated transcription; GO:0045944 positive regulation of transcription by RNA polymerase II; GO:0046600 negative regulation of centriole replication; GO:0051726 regulation of cell cycle; GO:0051865 protein autoubiquitination; GO:0061630 ubiquitin protein ligase activity; GO:0061649 ubiquitin-modified histone reader activity; GO:0070063 RNA polymerase binding; GO:0070531 BRCA1-A complex; GO:0070532 BRCA1-B complex; GO:0070533 BRCA1-C complex; GO:0071356 cellular response to tumor necrosis factor; GO:0071479 cellular response to ionizing radiation; GO:0071681 cellular response to indole-3-methanol; GO:0085020 protein K6-linked ubiquitination; GO:0110025 DNA strand resection involved in replication fork processing; GO:0140863 histone H2AK127 ubiquitin ligase activity; GO:0140864 histone H2AK129 ubiquitin ligase activity; GO:1902042 negative regulation of extrinsic apoptotic signaling pathway via death domain receptors; GO:1990391 DNA repair complex; GO:1990904 ribonucleoprotein complex; GO:2000001 regulation of DNA damage checkpoint; GO:2000378 negative regulation of reactive oxygen species metabolic process','E3 ubiquitin-protein ligase that specifically mediates the formation of \'Lys-6\'-linked polyubiquitin chains and plays a central role in DNA repair by facilitating cellular responses to DNA damage (PubMed:10500182, PubMed:12887909, PubMed:12890688, PubMed:14976165, PubMed:16818604, PubMed:17525340, PubMed:19261748). It is unclear whether it also mediates the formation of other types of polyubiquitin chains (PubMed:12890688). The BRCA1-BARD1 heterodimer coordinates a diverse range of cellular pathways such as DNA damage repair, ubiquitination and transcriptional regulation to maintain genomic stability (PubMed:12890688, PubMed:14976165, PubMed:20351172). Regulates centrosomal microtubule nucleation (PubMed:18056443). Required for appropriate cell cycle arrests after ionizing irradiation in both the S-phase and the G2 phase of the cell cycle (PubMed:10724175, PubMed:11836499, PubMed:12183412, PubMed:19261748). Required for FANCD2 targeting to sites of DNA damage (PubMed:12887909). Inhibits lipid synthesis by binding to inactive phosphorylated ACACA and preventing its dephosphorylation (PubMed:16326698). Contributes to homologous recombination repair (HRR) via its direct interaction with PALB2, fine-tunes recombinational repair partly through its modulatory role in the PALB2-dependent loading of BRCA2-RAD51 repair machinery at DNA breaks (PubMed:19369211). Component of the BRCA1-RBBP8 complex which regulates CHEK1 activation and controls cell cycle G2/M checkpoints on DNA damage via BRCA1-mediated ubiquitination of RBBP8 (PubMed:16818604). Acts as a transcriptional activator (PubMed:20160719)','Chromosome; Cytoplasm; Nucleus','Chromosome (ECO:0000269); Cytoplasm (ECO:0000269); Nucleus (ECO:0000269)','lookup_failed','reviewed_found','P48754','Breast cancer type 1 susceptibility protein homolog','GO:0000152 nuclear ubiquitin ligase complex; GO:0000724 double-strand break repair via homologous recombination; GO:0000793 condensed chromosome; GO:0000794 condensed nuclear chromosome; GO:0000800 lateral element; GO:0000976 transcription cis-regulatory region binding; GO:0001741 XY body; GO:0002039 p53 binding; GO:0003682 chromatin binding; GO:0003684 damaged DNA binding; GO:0003713 transcription coactivator activity; GO:0003723 RNA binding; GO:0004842 ubiquitin-protein transferase activity; GO:0005634 nucleus; GO:0005654 nucleoplasm; GO:0005694 chromosome; GO:0005737 cytoplasm; GO:0005759 mitochondrial matrix; GO:0005813 centrosome; GO:0005886 plasma membrane; GO:0006281 DNA repair; GO:0006282 regulation